    /// The key-only expansion of 6 lane(s) (`bc_expand0_*_6`): 521 encryptions chained from zero, filling P
    /// and then the S-boxes. Generic over the array's size (always 6) so the states are reached by address and
    /// never copied.
    @inline(__always) private static func expand0ShrxLanes6<let m: Int>(_ st: inout InlineArray<m, State>) {
        let by24 = shiftBy24.load(ordering: .relaxed), by16 = shiftBy16.load(ordering: .relaxed)
        var l0: UInt32 = 0, r0: UInt32 = 0; var l1: UInt32 = 0, r1: UInt32 = 0; var l2: UInt32 = 0, r2: UInt32 = 0; var l3: UInt32 = 0, r3: UInt32 = 0; var l4: UInt32 = 0, r4: UInt32 = 0; var l5: UInt32 = 0, r5: UInt32 = 0
        for i in 0..<9 {
            encipherShrx6(st, &l0, &r0, &l1, &r1, &l2, &r2, &l3, &r3, &l4, &r4, &l5, &r5, by24, by16)
            st[0].p[2 * i] = l0; st[0].p[2 * i + 1] = r0
            st[1].p[2 * i] = l1; st[1].p[2 * i + 1] = r1
            st[2].p[2 * i] = l2; st[2].p[2 * i + 1] = r2
            st[3].p[2 * i] = l3; st[3].p[2 * i + 1] = r3
            st[4].p[2 * i] = l4; st[4].p[2 * i + 1] = r4
            st[5].p[2 * i] = l5; st[5].p[2 * i + 1] = r5
        }
        for i in 0..<512 {
            encipherShrx6(st, &l0, &r0, &l1, &r1, &l2, &r2, &l3, &r3, &l4, &r4, &l5, &r5, by24, by16)
            st[0].s[2 * i] = l0; st[0].s[2 * i + 1] = r0
            st[1].s[2 * i] = l1; st[1].s[2 * i + 1] = r1
            st[2].s[2 * i] = l2; st[2].s[2 * i + 1] = r2
            st[3].s[2 * i] = l3; st[3].s[2 * i + 1] = r3
            st[4].s[2 * i] = l4; st[4].s[2 * i + 1] = r4
            st[5].s[2 * i] = l5; st[5].s[2 * i + 1] = r5
        }
    }

